require_once dirname(__DIR__,2).'/app/bootstrap.php';require_owner();$uid=current_user_id();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='event'){$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$venue=trim((string)($_POST['venue']??''));$location=trim((string)($_POST['location']??''));$start=trim((string)($_POST['starts_at']??''));$end=trim((string)($_POST['ends_at']??''));$url=valid_http_url((string)($_POST['organizer_url']??''));if($title===''||text_len($title)>140||text_len($desc)<30||$start==='')$errors[]='Enter an event title, start date and description of at least 30 characters.';if(!$errors){$slug=slugify($title).'-'.bin2hex(random_bytes(3));db()->prepare("INSERT INTO events(title,slug,description,venue,location,starts_at,ends_at,organizer_url,status,created_by) VALUES(:t,:s,:d,:v,:l,:st,:en,:u,'pending',:by)")->execute([':t'=>$title,':s'=>$slug,':d'=>$desc,':v'=>$venue,':l'=>$location,':st'=>str_replace('T',' ',$start),':en'=>$end?str_replace('T',' ',$end):'',':u'=>$url,':by'=>$uid]);flash('success','Event submitted for approval.');redirect(app_path('owner/index.php'));}}
 elseif($action==='offer'){$listingId=(int)($_POST['listing_id']??0);$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$code=trim((string)($_POST['promo_code']??''));$end=trim((string)($_POST['ends_at']??''));$own=db()->prepare('SELECT id FROM listings WHERE id=:l AND owner_user_id=:u');$own->execute([':l'=>$listingId,':u'=>$uid]);if(!$own->fetchColumn())$errors[]='Choose one of your verified business listings.';if($title===''||text_len($desc)<15)$errors[]='Enter an offer title and description of at least 15 characters.';if(!$errors){db()->prepare("INSERT INTO offers(listing_id,title,description,promo_code,ends_at,status,created_by) VALUES(:l,:t,:d,:c,:e,'pending',:u)")->execute([':l'=>$listingId,':t'=>$title,':d'=>$desc,':c'=>$code,':e'=>$end,':u'=>$uid]);flash('success','Offer submitted for approval.');redirect(app_path('owner/index.php'));}}
}
$ls=db()->prepare('SELECT * FROM listings WHERE owner_user_id=:u ORDER BY updated_at DESC');$ls->execute([':u'=>$uid]);$listings=$ls->fetchAll();$claims=db()->prepare('SELECT c.*,l.name FROM owner_claims c JOIN listings l ON l.id=c.listing_id WHERE c.user_id=:u ORDER BY c.created_at DESC');$claims->execute([':u'=>$uid]);$claims=$claims->fetchAll();$events=db()->prepare('SELECT title,status,starts_at FROM events WHERE created_by=:u ORDER BY created_at DESC LIMIT 8');$events->execute([':u'=>$uid]);$events=$events->fetchAll();$offers=db()->prepare('SELECT o.title,o.status,l.name listing_name FROM offers o JOIN listings l ON l.id=o.listing_id WHERE o.created_by=:u ORDER BY o.created_at DESC LIMIT 8');$offers->execute([':u'=>$uid]);$offers=$offers->fetchAll();$eventTotal=db()->prepare('SELECT COUNT(*) FROM events WHERE created_by=:u');$eventTotal->execute([':u'=>$uid]);$eventTotal=(int)$eventTotal->fetchColumn();$offerTotal=db()->prepare('SELECT COUNT(*) FROM offers WHERE created_by=:u');$offerTotal->execute([':u'=>$uid]);$offerTotal=(int)$offerTotal->fetchColumn();
$ownerTitle='Business owner portal';include __DIR__.'/_header.php';
?>
